#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<pair<int, int>> items(m);
    for (int i = 0; i < m; ++i)
        cin >> items[i].first >> items[i].second;

    sort(items.begin(), items.end(), [](const auto& a, const auto& b) {
        return a.second > b.second;
    });

    long long result = 0;
    int remaining = n;

    for (const auto& item : items) {
        int quantity = min(remaining, item.first);
        result += 1LL * quantity * item.second;
        remaining -= quantity;
        if (remaining == 0)
            break;
    }

    cout << result;
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    int m;
    cin >> n >> m;

    vector<pair<long long, long long>> items(m);
    for (auto& [quantity, value] : items)
        cin >> quantity >> value;

    sort(items.begin(), items.end(),
         [](const auto& a, const auto& b) {
             return a.second > b.second;
         });

    long long used = 0;
    long long result = 0;

    for (const auto& [quantity, value] : items) {
        long long take = min(quantity, n - used);
        result += take * value;
        used += take;

        if (used == n)
            break;
    }

    cout << result;
    return 0;
}

