#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> t1(m), t2(m);
    for (int i = 0; i < m; ++i) {
        cin >> t1[i] >> t2[i];
    }

    int cpt = 0;
    long long r = 0;

    while (cpt < n) {
        int vm = 0;
        for (int i = 1; i < m; ++i) {
            if (t2[i] > t2[vm]) {
                vm = i;
            }
        }

        int quantity = min(t1[vm], n - cpt);
        r += 1LL * quantity * t2[vm];
        cpt += quantity;
        t1[vm] = 0;
        t2[vm] = 0;
    }

    cout << r;
    return 0;
}

